gmd(){return"\uac1c\uc778\uc815\ubcf4\ucc98\ub9ac\ubc29\uce68"},
rD(a){return"\ucd5c\uc885 \uc5c5\ub370\uc774\ud2b8: "+a},
grQ(){return"TruthLens\ub294 \ube0c\ub77c\uc6b0\uc800 \ud0ed\uc5d0\uc11c \uc644\uc804\ud788 \uc6f9 \uc571\uc73c\ub85c \uc2e4\ud589\ub429\ub2c8\ub2e4. \uc124\uce58\ud560 \ud544\uc694\uac00 \uc5c6\uc73c\uba70, \ubb38\uc11c \ud14d\uc2a4\ud2b8\uc640 \ubd84\uc11d \uacb0\uacfc\ub294 \uae30\uae30\ub97c \ubc97\uc5b4\ub098\uc9c0 \uc54a\uace0, \ub2e4\uc6b4\ub85c\ub4dc\ub41c \uac10\uc9c0 \ubaa8\ub378\uc740 \uc11c\ubc84\uac00 \uc544\ub2cc \ube0c\ub77c\uc6b0\uc800 \uc790\uccb4\uc758 \uc0cc\ub4dc\ubc15\uc2a4 \uc800\uc7a5\uc18c\uff08OPFS\uff09\uc5d0\ub9cc \uce90\uc2dc\ub429\ub2c8\ub2e4."},
grR(){return"\uc774 \ud398\uc774\uc9c0\ub294 \uc0ac\uc6a9\uc790\uac00 \uc801\uadf9\uc801\uc73c\ub85c \uac00\uc838\uc624\uae30, \uc2a4\uce94 \ub610\ub294 \ubd99\uc5ec\ub123\uae30\ub97c \uc120\ud0dd\ud560 \ub54c\ub9cc \ud30c\uc77c, \uc774\ubbf8\uc9c0 \ub610\ub294 \ud074\ub9bd\ubcf4\ub4dc \ucf58\ud150\uce20\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub2e4\ub978 \ud0ed, \ub2e4\ub978 \uc0ac\uc774\ud2b8\uc758 \ub370\uc774\ud130 \ub610\ub294 \uc120\ud0dd\ud558\uc9c0 \uc54a\uc740 \ud30c\uc77c\uc740 \uc808\ub300 \uc77d\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
grO(){return"\uac1c\uc694"},
grJ(){return"\ube0c\ub77c\uc6b0\uc800 \uc124\uc815\uc5d0\uc11c \uc774 \uc0ac\uc774\ud2b8\uc758 \ub370\uc774\ud130\ub97c \uc9c0\uc6b0\uae30\uff08\ub610\ub294 \uc11c\ubc84\uc5d0 \uc800\uc7a5\ub41c \uac83\uc774 \uc5c6\uc73c\ubbc0\ub85c \ud0ed\uc744 \ub2eb\uae30\ub9cc \ud574\ub3c4 \ub429\ub2c8\ub2e4\uff09"},
grz(){return"TruthLens\uc5d0\ub294 \uc0ac\uc6a9\uc790 \uacc4\uc815\uc774 \uc5c6\uc73c\uba70 \ub85c\uadf8\uc778\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\uace0, \uc5b4\ub5a4 \ud615\ud0dc\uc758 \uad11\uace0\ub098 \uc81c3\uc790 \ucd94\uc801 SDK\ub3c4 \ud3ec\ud568\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
grA(){return"\uc0ac\uc6a9\uc790\uac00 \uc785\ub825, \ubd99\uc5ec\ub123\uae30 \ub610\ub294 \uac00\uc838\uc628 \ubb38\uc11c \ub0b4\uc6a9\uc740 \ubaa8\ub450 \uc0ac\uc6a9\uc790\uc758 \uae30\uae30\uc5d0\uc11c \ub85c\uceec AI \ubaa8\ub378\uc5d0 \uc758\ud574 \ubd84\uc11d\ub418\uba70, TruthLens\ub098 \uc5b4\ub5a4 \uc81c3\uc790 \uc11c\ubc84\uc5d0\ub3c4 \uc5c5\ub85c\ub4dc\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
grB(){return"\ubd84\uc11d \uacb0\uacfc\uc640 \uae30\ub85d\uc740 \uc0ac\uc6a9\uc790 \uae30\uae30\uc758 \ub85c\uceec \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc5d0\ub9cc \uc800\uc7a5\ub429\ub2c8\ub2e4. \uc571\uc744 \uc0ad\uc81c\ud558\uac70\ub098 \uae30\ub85d\uc744 \uc9c0\uc6b0\uba74 \ud568\uaed8 \uc81c\uac70\ub418\uba70, TruthLens\ub294 \uc5b4\ub5a4 \uc0ac\ubcf8\ub3c4 \ubcf4\uad00\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
grI(){return"\uc774 \uc571\uc758 \ud575\uc2ec AI \uac10\uc9c0\ub294 \uc644\uc804\ud788 \uae30\uae30 \ub0b4\uc5d0\uc11c \uc2e4\ud589\ub418\uc9c0\ub9cc, \ub2e4\uc74c \uc138 \uac00\uc9c0 \uae30\ub2a5\uc740 \ub124\ud2b8\uc6cc\ud06c \uc5f0\uacb0\uc774 \ud544\uc694\ud569\ub2c8\ub2e4:"},
grE(){return"1. \ubaa8\ub378 \uce74\ud0c8\ub85c\uadf8 \ubc0f \ub2e4\uc6b4\ub85c\ub4dc: GitHub Releases\uff0fHugging Face\uc5d0 \uc5f0\uacb0\ud558\uc5ec \uc120\ud0dd\ud55c \uac10\uc9c0 \ubaa8\ub378 \ud30c\uc77c\uc744 \ub2e4\uc6b4\ub85c\ub4dc\ud569\ub2c8\ub2e4. \ubaa8\ub378 \ub2e4\uc6b4\ub85c\ub4dc\ub9cc \uc218\ud589\ud558\uba70 \uc0ac\uc6a9\uc790 \ub370\uc774\ud130\ub97c \uc5c5\ub85c\ub4dc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
grF(){return"2. \ubaa8\ub378 \uc5c5\ub370\uc774\ud2b8 \ud655\uc778: \uc2e4\ud589 \uc2dc \ubc84\uc804 \ubc88\ud638\ub9cc \ube44\uad50\ud558\uae30 \uc704\ud574 \uc5f0\uacb0\ud558\uba70, \uc0c8 \ubc84\uc804\uc774 \uc788\ub294\uc9c0 \uc54c\ub9ac\ub294 \ub370 \uc0ac\uc6a9\ub429\ub2c8\ub2e4."},
grG(){return'3. \ud558\uc774\ud37c\ub9c1\ud06c \ubc0f \uc778\uc6a9 \ubb38\ud5cc \uc2e4\uc7ac\uc131 \uac80\uc99d: \uae30\ubcf8\uc801\uc73c\ub85c \ucf1c\uc838 \uc788\uc73c\uba70 "\uc124\uc815"\uc5d0\uc11c \ub04c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ucf1c\uc838 \uc788\uc73c\uba74 \ubb38\uc11c\uc5d0\uc11c \uac10\uc9c0\ub41c URL\uc774\ub098 \ucc38\uace0 \ubb38\ud5cc \ud14d\uc2a4\ud2b8\ub97c \ud574\ub2f9 URL \uc790\uccb4 \ub610\ub294 Crossref \uacf5\uac1c API\ub85c \uc9c1\uc811 \uc804\uc1a1\ud569\ub2c8\ub2e4. URL\uff0fDOI\uff0f\uc11c\uc9c0 \uc815\ubcf4 \ud14d\uc2a4\ud2b8\ub9cc \uc804\uc1a1\ud558\uba70 \ubb38\uc11c\uc758 \ub2e4\ub978 \ub0b4\uc6a9\uc740 \ud3ec\ud568\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.'},
grH(){return"4. \uc6f9 OCR \ub300\uccb4: \uc6f9 \ubc84\uc804\uc5d0\uc11c\ub9cc OCR\uc740 \uad6c\uc131\ub41c \uacbd\uc6b0 \ub85c\uceec OCR \uc11c\ubc84\ub97c \uba3c\uc800 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. Gemini API \ud0a4\ub97c \uc785\ub825\ud558\ub3c4\ub85d \uc120\ud0dd\ud55c \uacbd\uc6b0, \uc120\ud0dd\ud55c \uc774\ubbf8\uc9c0\uc640 OCR\uc774 \ud544\uc694\ud55c PDF \ub80c\ub354\ub9c1 \ud398\uc774\uc9c0\uac00 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c Google\uc758 Gemini API\ub85c \uc9c1\uc811 \uc804\uc1a1\ub429\ub2c8\ub2e4. \ud0a4\ub294 \ud574\ub2f9 \ube0c\ub77c\uc6b0\uc800\uc758 \ub85c\uceec \uc800\uc7a5\uc18c\uc5d0\ub9cc \uc800\uc7a5\ub429\ub2c8\ub2e4."},
grK(){return'"\uae30\ub85d"\uc5d0\uc11c \uc5b8\uc81c\ub4e0\uc9c0 \ub85c\uceec \ubd84\uc11d \uae30\ub85d\uc744 \uc9c0\uc6b0\uac70\ub098 "\uc124\uc815"\uc5d0\uc11c \ud558\uc774\ud37c\ub9c1\ud06c\uff0f\ubb38\ud5cc \uac80\uc99d \uae30\ub2a5\uc744 \ub04c \uc218 \uc788\uc73c\uba70, \ub610\ub294 \uc9c1\uc811'},
