lP(a){return'"'+a+'" \u043d\u0435 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0447\u0438\u0442\u0430\u0435\u043c\u043e\u0433\u043e \u0442\u0435\u043a\u0441\u0442\u0430'},
lQ(a,b){return'"'+a+'" \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043d ('+b+" \u0441\u0438\u043c\u0432\u043e\u043b\u043e\u0432)"},
lW(a,b){return"\u0422\u0435\u043a\u0441\u0442\u043e\u0432\u044b\u0439 \u0441\u043b\u043e\u0439 PDF \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d; \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0451\u0442\u0441\u044f \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0430 "+a+" \u0438\u0437 "+b+" \u0441 \u043f\u043e\u043c\u043e\u0449\u044c\u044e OCR\u2026"},
lX(a,b){return"\u0424\u0430\u0439\u043b \xab"+a+"\xbb \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043d \u0441 \u043f\u043e\u043c\u043e\u0449\u044c\u044e OCR PDF ("+b+" \u0441\u0438\u043c\u0432\u043e\u043b\u043e\u0432)"},
lV(a){return"\u0412 \u0444\u0430\u0439\u043b\u0435 \xab"+a+"\xbb \u043d\u0435\u0442 \u043d\u0430\u0434\u0451\u0436\u043d\u043e\u0433\u043e \u0442\u0435\u043a\u0441\u0442\u043e\u0432\u043e\u0433\u043e \u0441\u043b\u043e\u044f. \u041d\u0430\u0441\u0442\u0440\u043e\u0439\u0442\u0435 \u0432\u0435\u0431-OCR \u0438\u043b\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0439\u0442\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0441 \u043d\u0430\u0442\u0438\u0432\u043d\u044b\u043c OCR, \u0437\u0430\u0442\u0435\u043c \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u0439\u0442\u0435 \u0444\u0430\u0439\u043b \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e."},
lY(a,b){return"\u0424\u0430\u0439\u043b\u0443 \xab"+a+"\xbb \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f OCR, \u043d\u043e \u043e\u043d \u043f\u0440\u0435\u0432\u044b\u0448\u0430\u0435\u0442 \u043b\u0438\u043c\u0438\u0442 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u0432 "+b+" \u0441\u0442\u0440\u0430\u043d\u0438\u0446. \u0420\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u0435 PDF \u0438 \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u0439\u0442\u0435 \u043a\u0430\u0436\u0434\u0443\u044e \u0447\u0430\u0441\u0442\u044c."},
lZ(a){return"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043d\u0430\u0434\u0451\u0436\u043d\u043e \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u0444\u0430\u0439\u043b \xab"+a+"\xbb. \u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u043e\u043d \u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0451\u043d, \u0437\u0430\u0449\u0438\u0449\u0451\u043d \u043f\u0430\u0440\u043e\u043b\u0435\u043c \u0438\u043b\u0438 \u043d\u0435 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043d\u0430\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u043e\u0439 \u0441\u043b\u0443\u0436\u0431\u043e\u0439 OCR."},
lO(a){return"\xab"+a+"\xbb \u2014 \u044d\u0442\u043e \u0444\u0430\u0439\u043b \u0432 \u0443\u0441\u0442\u0430\u0440\u0435\u0432\u0448\u0435\u043c \u0444\u043e\u0440\u043c\u0430\u0442\u0435 .doc, \u0442\u0435\u043a\u0441\u0442 \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u043d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043d\u0430\u0434\u0451\u0436\u043d\u043e \u0438\u0437\u0432\u043b\u0435\u0447\u044c. \u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0435 \u0435\u0433\u043e \u043a\u0430\u043a .docx \u0432 Word \u0438\u043b\u0438 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u0439\u0442\u0435 \u0432 PDF, \u0437\u0430\u0442\u0435\u043c \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u0439\u0442\u0435 \u0441\u043d\u043e\u0432\u0430."},
qA(a){return"\u041c\u043e\u0434\u0435\u043b\u044c: "+a},
gqE(){return"\u041c\u043e\u0434\u0435\u043b\u044c \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0430 (\u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439/\u0441\u0442\u0438\u043b\u043e\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0430\u043d\u0430\u043b\u0438\u0437)"},
kS(a){return""+a+" \u0441\u0438\u043c\u0432\u043e\u043b\u043e\u0432"},
giI(){return"\u041a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 Transformer"},
