gqU(){return"\u0421\u043a\u043e\u0440\u043e"},
gm9(){return"\u0421\u0434\u0435\u043b\u0430\u0442\u044c \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0439"},
gr6(){return"\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c"},
